KG42.register("rules-5fbf6e41d8e3b81e28614366",{"id":"34-market_versus_price_scheduling::v141-c-R006","paper":"34-market_versus_price_scheduling","record":{"rule_id":"v141-c-R006","mechanism_id":"v141-a-M01","name":"Energy-trade execution","process_stage":"activation","market_meaning":"A microgrid may exchange power with the main grid and act as a player in the electricity market. Scope: Microgrids in the proposed DMO-based distribution market. Main-grid power transfer is restricted by the capacity limits of the line connecting the microgrid to the main grid. Scope: Main-grid power transfer in the proposed microgrid scheduling model. Main-grid power transfer is zero during islanded operation. Scope: Main-grid power transfer in the proposed microgrid scheduling model. Condition: The islanding indicator U is 0 (islanded operation). Positive deviations of scheduled main-grid power transfer from the DMO assignment are penalized. Scope: The proposed model's positive-deviation-only penalty policy. Condition: The microgrid's scheduled power exceeds the power assigned by the DMO. Negative power-transfer deviations are not penalized under the proposed policy. Scope: The proposed model's positive-deviation-only penalty policy. Condition: The scheduled main-grid power transfer has a negative deviation from the DMO assignment. Under the absolute-deviation penalty, the microgrid is obligated to closely follow the scheduled power transfer. Scope: The alternative numerical scenario using an absolute-deviation penalty. Condition: The absolute value of power-transfer deviations is penalized.","independence_rationale":"Relations governed by the approved function execution.energy_trade under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["execution.energy_trade"],"E":[],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"Main-grid power transfer in the proposed microgrid scheduling model. | Microgrids in the proposed DMO-based distribution market. | The alternative numerical scenario using an absolute-deviation penalty. | The proposed model's positive-deviation-only penalty policy.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e004","v141-b-g01-e016","v141-b-g01-e025","v141-b-g01-e027","v141-b-g02-E29"]},"x":[{"variable_id":"v141-c-R006-X001","symbol":"P^{M}_{mt}","meaning":"Scheduled main-grid power transfer to microgrid m at time t, as used in the microgrid market-based optimal scheduling problem.","kind":"operational","domain":"real-valued signed power transfer bounded by Eq. (6)","unit":"MW","indices":["m","t"],"evidence_ids":["v141-b-g01-e003","v141-b-g01-e021","v141-b-g01-e027"]},{"variable_id":"v141-c-R006-X002","symbol":"\\Delta P^{M}_{mt}","meaning":"Power-transfer deviation, equal to scheduled main-grid power transfer minus the DMO-assigned power in Eq. (7).","kind":"operational","domain":"real","unit":"MW","indices":["m","t"],"evidence_ids":["v141-b-g01-e003","v141-b-g01-e022","v141-b-g01-e027"]},{"variable_id":"v141-c-R006-X003","symbol":"\\Delta P^{M+}_{mt}","meaning":"Positive power-transfer deviation selected by constraints (8)-(10) and penalized in the objective.","kind":"operational","domain":"nonnegative real as constrained by (8)-(10)","unit":"MW","indices":["m","t"],"evidence_ids":["v141-b-g01-e003","v141-b-g01-e023","v141-b-g01-e024","v141-b-g01-e027"]},{"variable_id":"v141-c-R006-X004","symbol":"\\delta_{mt}","meaning":"Binary power-transfer deviation indicator used to select whether the positive deviation is penalized.","kind":"operational","domain":"{0,1}","unit":null,"indices":["m","t"],"evidence_ids":["v141-b-g01-e003","v141-b-g01-e023","v141-b-g01-e024","v141-b-g01-e027"]}],"theta":[{"parameter_id":"v141-c-R006-T001","symbol":"PD^{M}_{mt}","meaning":"Assigned demand/power to microgrids by the DMO, used as the fixed reference against which scheduled main-grid power transfer is compared in Eq. (7).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"MW","indices":["m","t"],"evidence_ids":["v141-b-g01-e003","v141-b-g01-e022","v141-b-g01-e027"]},{"parameter_id":"v141-c-R006-T002","symbol":"\\nu_m","meaning":"Penalty coefficient for scheduled power deviation, multiplying the positive power-transfer deviation in objective term (1).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["m"],"evidence_ids":["v141-b-g01-e004","v141-b-g01-e018","v141-b-g01-e025"]},{"parameter_id":"v141-c-R006-T003","symbol":"P^{M,\\max}_{m}","meaning":"Maximum main-grid power transfer imposed by the capacity of the line connecting microgrid m to the main grid, used in Eq. (6).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"MW","indices":["m"],"evidence_ids":["v141-b-g01-e021","v141-b-g01-e027"]},{"parameter_id":"v141-c-R006-T004","symbol":"U_{mt}","meaning":"Islanding indicator: 1 when grid-connected and 0 when islanded; Eq. (6) zeroes main-grid transfer when it is 0.","value":{"kind":"symbolic","number_value":null,"text_value":"0 or 1"},"unit":null,"indices":["m","t"],"evidence_ids":["v141-b-g01-e004","v141-b-g01-e021","v141-b-g01-e027"]},{"parameter_id":"v141-c-R006-T005","symbol":"\\varepsilon","meaning":"Small positive offset appearing in Eq. (10); the source does not state its value.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g01-e024"]}],"phi":[{"constraint_id":"v141-c-R006-C001","kind":"procedural","role":"core","statement":"A microgrid may exchange power with the main grid and act as a player in the electricity market. Scope: Microgrids in the proposed DMO-based distribution market.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e016"]},{"constraint_id":"v141-c-R006-C002","kind":"mathematical","role":"core","statement":"Main-grid power transfer is restricted by the capacity limits of the line connecting the microgrid to the main grid. Scope: Main-grid power transfer in the proposed microgrid scheduling model.","expression":"-P^{M,\\max}_{m} U_{mt} \\le P^{M}_{mt} \\le P^{M,\\max}_{m} U_{mt} \\quad \\forall t \\quad (6)","formalization_origin":"source","template_id":null,"members":["execution.energy_trade"],"variable_refs":["v141-c-R006-X001"],"parameter_refs":["v141-c-R006-T003","v141-c-R006-T004"],"evidence_ids":["v141-b-g01-e027","v141-b-g01-e021"]},{"constraint_id":"v141-c-R006-C003","kind":"mathematical","role":"core","statement":"Main-grid power transfer is zero during islanded operation. Scope: Main-grid power transfer in the proposed microgrid scheduling model. Condition: The islanding indicator U is 0 (islanded operation).","expression":"U_{mt}=0 \\;\\Rightarrow\\; P^{M}_{mt}=0","formalization_origin":"equivalent_translation","template_id":null,"members":["execution.energy_trade"],"variable_refs":["v141-c-R006-X001"],"parameter_refs":["v141-c-R006-T004"],"evidence_ids":["v141-b-g01-e004","v141-b-g01-e027","v141-b-g01-e021"]},{"constraint_id":"v141-c-R006-C004","kind":"mathematical","role":"core","statement":"Positive deviations of scheduled main-grid power transfer from the DMO assignment are penalized. Scope: The proposed model's positive-deviation-only penalty policy. Condition: The microgrid's scheduled power exceeds the power assigned by the DMO.","expression":"\\Delta P^{M}_{mt} = P^{M}_{mt} - PD^{M}_{mt} \\quad \\forall t \\quad (7)\\n-P^{M,\\max}_{m}\\delta_{mt} \\le \\Delta P^{M+}_{mt} \\le P^{M,\\max}_{m}\\delta_{mt} \\quad \\forall t \\quad (8)\\n-P^{M,\\max}_{m}(1-\\delta_{mt}) \\le \\Delta P^{M}_{mt}-\\Delta P^{M+}_{mt} \\le P^{M,\\max}_{m}(1-\\delta_{mt}) \\quad \\forall t \\quad (9)\\n-P^{M,\\max}_{m}(1-\\delta_{mt})+\\varepsilon \\le \\Delta P^{M}_{mt} \\le P^{M,\\max}_{m}\\delta_{mt} \\quad \\forall t \\quad (10)\\n\\text{penalty term in (1): } \\nu_m \\Delta P^{M+}_{mt}","formalization_origin":"source","template_id":null,"members":["execution.energy_trade"],"variable_refs":["v141-c-R006-X001","v141-c-R006-X002","v141-c-R006-X003","v141-c-R006-X004"],"parameter_refs":["v141-c-R006-T001","v141-c-R006-T002","v141-c-R006-T003","v141-c-R006-T005"],"evidence_ids":["v141-b-g01-e025","v141-b-g01-e018","v141-b-g01-e022","v141-b-g01-e023","v141-b-g01-e024","v141-b-g01-e026","v141-b-g01-e027"]},{"constraint_id":"v141-c-R006-C005","kind":"mathematical","role":"core","statement":"Negative power-transfer deviations are not penalized under the proposed policy. Scope: The proposed model's positive-deviation-only penalty policy. Condition: The scheduled main-grid power transfer has a negative deviation from the DMO assignment.","expression":"\\Delta P^{M}_{mt}\\le 0 \\;\\Rightarrow\\; \\delta_{mt}=0,\\; \\Delta P^{M+}_{mt}=0 \\quad \\text{(from (8)-(10)); no }\\nu_m\\Delta P^{M+}_{mt}\\text{ penalty}","formalization_origin":"equivalent_translation","template_id":null,"members":["execution.energy_trade"],"variable_refs":["v141-c-R006-X002","v141-c-R006-X003","v141-c-R006-X004"],"parameter_refs":[],"evidence_ids":["v141-b-g01-e025","v141-b-g01-e023","v141-b-g01-e024","v141-b-g01-e027"]},{"constraint_id":"v141-c-R006-C006","kind":"mathematical","role":"core","statement":"Under the absolute-deviation penalty, the microgrid is obligated to closely follow the scheduled power transfer. Scope: The alternative numerical scenario using an absolute-deviation penalty. Condition: The absolute value of power-transfer deviations is penalized.","expression":"\\text{penalized quantity} = \\left|\\Delta P^{M}_{mt}\\right|","formalization_origin":"equivalent_translation","template_id":null,"members":["execution.energy_trade"],"variable_refs":["v141-c-R006-X002"],"parameter_refs":[],"evidence_ids":["v141-b-g02-E29","v141-b-g03-e03","v141-b-g03-e08","v141-b-g03-e09"]}],"pi":[{"evidence_id":"v141-b-g01-e004","location":{"location_id":"src-b66ae5184e-p01-c2r2__v141-a-M01-clearing","page":1,"printed_page":null,"section":"Nomenclature","anchor_text":"ar- U Islanding indicator (1 when grid-connected, on 0 when islanded). his ν Penalty for scheduled p","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"U Islanding indicator (1 when grid-connected, 0 when islanded). \\nu Penalty for scheduled power deviation. \\upsilon Value of lost load. x Line impedance. \\rho(P) Cost function of generation units submitted to the ISO. \\lambda(D) Consumption benefit of aggregated loads."},{"evidence_id":"v141-b-g01-e016","location":{"location_id":"src-b66ae5184e-p04-c1r3__v141-a-M01-coordination","page":4,"printed_page":null,"section":"III. Model Outline","anchor_text":"y y manageable peak demands and increased operational reli- ability and efﬁciency. Microgrids will h","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"The microgrid can exchange power with the main grid and act as a player in the electricity market. The DMO would serve as an intermediate entity between the ISO and microgrids that facilitates microgrids market participation and coordinates the microgrids with the main grid to minimize the risks posed by microgrids operational uncertainties."},{"evidence_id":"v141-b-g01-e025","location":{"location_id":"src-b66ae5184e-p04-c2r1__v141-a-M01-pricing","page":4,"printed_page":null,"section":"III. Model Outline","anchor_text":"IEEE TRANSACTIONS ON SMART GRID, VOL. 9, NO. 2, MARCH 2018 the assigned value will be penalized base","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"It will be assumed that deviations from the assigned value will be penalized based on the market price or a relatively larger value that can effectively prevent and/or reduce deviations. In this paper, it is assumed that the penalty will be applied when the deviation is positive, i.e., the microgrid’s scheduled power is larger than the assigned power by the DMO, or in other words, when the microgrid appears as a larger load compared to the assigned power by the DMO. Negative deviation will not be penalized in the proposed model as the microgrid helps with reducing load (increasing generation) in the distribution network."},{"evidence_id":"v141-b-g01-e027","location":{"location_id":"src-b66ae5184e-p05-c1r4__v141-a-M01-clearing","page":5,"printed_page":null,"section":"A. Microgrid","anchor_text":"its associated limits (imposed by the capacity of the line connecting the microgrid to the main grid","equation_id":"Eqs. (7)-(10)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"The main grid power transfer is restricted by its associated limits (imposed by the capacity of the line connecting the microgrid to the main grid) in (6). The islanding is modeled using a binary islanding indicator U which would zero out the main grid power transfer when 0. The main grid power deviation to be penalized in the objective is determined in (7)-(10). Constraint (7) calculates the deviation by subtracting the scheduled power via the optimal scheduling, PM, by the assigned power from the DMO, PDM. Constraints (8)-(10) determine the penalty if the calculated deviation is positive. An auxiliary binary variable δ is used for this purpose. When δ = 0 the power transfer to be penalized is zero, i.e., the scheduled power is less than the assigned power. However, when δ = 1 the power transfer to be penalized is equal to the positive deviation calculated in (7)."},{"evidence_id":"v141-b-g02-E29","location":{"location_id":"src-b66ae5184e-p08-c2r1__v141-a-M01-pricing","page":8,"printed_page":null,"section":"V. Numerical Simulations","anchor_text":"IEEE TRANSACTIONS ON SMART GRID, VOL. 9, NO. 2, MARCH 2018 hours and uses its own resources that bec","equation_id":null,"figure_id":"Fig. 8","table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"example"},"source_text":"When the absolute value of the deviations is penalized, the total microgrid operation cost rises to $50,539, as microgrid is obligated to closely follow the scheduled power transfer and hence would reduce generation of some its resources to purchase more power from the main grid, which results in a higher operation cost. This shows that penalizing power deviation is key to ensuring certainty in the power scheduled by the DMO. Penalizing the absolute value of power deviation can increase the microgrid operation cost, even if the power deviation would result in a surplus of power which is manageable by the system operator. The decision to penalize only the positive deviations or the absolute deviation should be made by the distribution system operator based on the probable congestion scenarios."},{"evidence_id":"v141-b-g01-e003","location":{"location_id":"src-b66ae5184e-p01-c2r3__v141-a-M01-clearing","page":1,"printed_page":null,"section":"Nomenclature","anchor_text":"DXmax Segment in the variable load bid of the microgrid. I Commitment state of dispatchable unit (1 ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"d Load demand. D The demand awarded from the ISO to the DMO. PD^M Assigned demand to microgrids by the DMO. DX The amount of load awarded to each segment of the bid. DX^max Segment in the variable load bid of the microgrid. I Commitment state of dispatchable unit (1 when committed, 0 otherwise). LS Load curtailment. P DER output power. P^M Scheduled power transfer from the DMO to the microgrid. PL Line flow. \\Delta P^M Power transfer deviation. \\Delta P^{M+} Positive power transfer deviation. \\delta Power transfer deviation indicator (1 when deviation is positive, 0 otherwise). \\theta Bus angle."},{"evidence_id":"v141-b-g01-e018","location":{"location_id":"src-b66ae5184e-p04-c2r3__v141-a-M01-clearing","page":4,"printed_page":null,"section":"A. Microgrid","anchor_text":"li- SCHEDULING PROBLEM FORMULATION ity The discussed three levels of the market structure are her fo","equation_id":"Eqs. (1)-(10)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"\\min \\sum_t \\sum_i \\left[ F_{im}(P_{imt}, I_{imt}) + \\upsilon_m LS_{mt} + \\nu_m \\Delta P^{M+}_{mt} \\right] \\quad (1)"},{"evidence_id":"v141-b-g01-e021","location":{"location_id":"src-b66ae5184e-p04-c2r4__v141-a-M01-clearing","page":4,"printed_page":null,"section":"A. Microgrid","anchor_text":"he t i MO PMmt + Pimt + LSmt = dmt ∀t (2) ent i us- Pminim Iimt ≤Pimt ≤Pmaxim Iimt ∀t, ∀i (3) nd, v-","equation_id":"Eqs. (2)-(9)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"-P^{M,max}_m U_{mt} \\le P^M_{mt} \\le P^{M,max}_m U_{mt} \\quad \\forall t \\quad (6)"},{"evidence_id":"v141-b-g01-e022","location":{"location_id":"src-b66ae5184e-p04-c2r4__v141-a-M01-clearing","page":4,"printed_page":null,"section":"A. Microgrid","anchor_text":"he t i MO PMmt + Pimt + LSmt = dmt ∀t (2) ent i us- Pminim Iimt ≤Pimt ≤Pmaxim Iimt ∀t, ∀i (3) nd, v-","equation_id":"Eqs. (2)-(9)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"\\Delta P^M_{mt} = P^M_{mt} - PD^M_{mt} \\quad \\forall t \\quad (7)"},{"evidence_id":"v141-b-g01-e023","location":{"location_id":"src-b66ae5184e-p04-c2r4__v141-a-M01-clearing","page":4,"printed_page":null,"section":"A. Microgrid","anchor_text":"he t i MO PMmt + Pimt + LSmt = dmt ∀t (2) ent i us- Pminim Iimt ≤Pimt ≤Pmaxim Iimt ∀t, ∀i (3) nd, v-","equation_id":"Eqs. (2)-(9)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"-P^{M,max}\\delta_{mt} \\le \\Delta P^{M+}_{mt} \\le P^{M,max}\\delta_{mt} \\quad \\forall t \\quad (8)\\n-P^{M,max}(1-\\delta_{mt}) \\le \\Delta P^M_{mt} - \\Delta P^{M+}_{mt} \\le P^{M,max}(1-\\delta_{mt}) \\quad \\forall t \\quad (9)"},{"evidence_id":"v141-b-g01-e024","location":{"location_id":"src-b66ae5184e-p05-c1r1__v141-a-M01-clearing","page":5,"printed_page":null,"section":"A. Microgrid","anchor_text":"PARHIZI et al.: MARKET-BASED VERSUS PRICE-BASED MICROGRID OPTIMAL SCHE −PM,max(1 −δmt) + ε ≤ PMmt ≤P","equation_id":"Eq. (10)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"-P^{M,max}(1-\\delta_{mt}) + \\varepsilon \\le \\Delta P^M_{mt} \\le P^{M,max}\\delta_{mt} \\quad \\forall t \\quad (10)"},{"evidence_id":"v141-b-g01-e026","location":{"location_id":"src-b66ae5184e-p05-c1r2__v141-a-M01-clearing","page":5,"printed_page":null,"section":"A. Microgrid","anchor_text":"to have reliable uninterrupted service. It is commonly used as a measure of load criticality [47]. T","equation_id":"Eqs. (2)-(10)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"restatement"},"source_text":"The three terms in the objective function (1) represent the operation cost, the load curtailment cost, and the deviation cost, respectively. The operation cost is the cost of power production as well as startup and shut down costs of dispatchable units. The load curtailment cost is defined as the value of lost load times the amount of load curtailment. The value of lost load is assumed as an opportunity cost based on the cost that the consumer is willing to pay to have reliable uninterrupted service. It is commonly used as a measure of load criticality [47]. The deviation cost is the penalty imposed on the microgrid in case the microgrid schedule deviates from the power transfer assigned by the DMO."},{"evidence_id":"v141-b-g03-e03","location":{"location_id":"src-b66ae5184e-p08-c2r1__v141-a-M01-pricing","page":8,"printed_page":null,"section":"V. Numerical Simulations","anchor_text":"IEEE TRANSACTIONS ON SMART GRID, VOL. 9, NO. 2, MARCH 2018 hours and uses its own resources that bec","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"example"},"source_text":"The decision to penalize only the positive deviations or the absolute deviation should be made by the distribution system operator based on the probable congestion scenarios."},{"evidence_id":"v141-b-g03-e08","location":{"location_id":"src-b66ae5184e-p08-c1r4__v141-a-M01-pricing","page":8,"printed_page":null,"section":"V. Numerical Simulations","anchor_text":"operation cost will however decrease. Thus it can be seen that [6 higher penalties reduce the amount","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"condition"},"source_text":"When the absolute value of the deviations is penalized, the total microgrid operation cost rises to $50,539, as microgrid is obligated to closely follow the scheduled power transfer and hence would reduce generation of some its resources to purchase more power from the main grid, which results in a higher operation cost."},{"evidence_id":"v141-b-g03-e09","location":{"location_id":"src-b66ae5184e-p08-c2r1__v141-a-M01-pricing","page":8,"printed_page":null,"section":"V. Numerical Simulations","anchor_text":"IEEE TRANSACTIONS ON SMART GRID, VOL. 9, NO. 2, MARCH 2018 hours and uses its own resources that bec","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"example"},"source_text":"Penalizing the absolute value of power deviation can increase the microgrid operation cost, even if the power deviation would result in a surplus of power which is manageable by the system operator."}],"field_notes":{"empty_E_reason":"C explicitly supplied only source-backed unary facts for this function; other graph gaps remain reviewable.","empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-participation","v141-a-M01-pricing"],"extras":{"decision_anchor":"execution.energy_trade","graph_fact_supports":[[{"evidence_id":"v141-b-g01-e016","quote":"The microgrid can exchange power with the main grid and act as a player in the electricity market."}],[{"evidence_id":"v141-b-g01-e027","quote":"The main grid power transfer is restricted by its associated limits (imposed by the capacity of the line connecting the microgrid to the main grid) in (6)."}],[{"evidence_id":"v141-b-g01-e027","quote":"The islanding is modeled using a binary islanding indicator U which would zero out the main grid power transfer when 0."},{"evidence_id":"v141-b-g01-e004","quote":"U Islanding indicator (1 when grid-connected, 0 when islanded)."}],[{"evidence_id":"v141-b-g01-e025","quote":"the penalty will be applied when the deviation is positive, i.e., the microgrid’s scheduled power is larger than the assigned power by the DMO"}],[{"evidence_id":"v141-b-g01-e025","quote":"Negative deviation will not be penalized in the proposed model as the microgrid helps with reducing load (increasing generation) in the distribution network."}],[{"evidence_id":"v141-b-g02-E29","quote":"When the absolute value of the deviations is penalized, the total microgrid operation cost rises to $50,539, as microgrid is obligated to closely follow the scheduled power transfer and hence would reduce generation of some its resources to purchase more power from the main grid, which results in a higher operation cost."}]],"C2_formalization":{"graph_sha256":"5b97ac84d45ec48d51ccf48d4e4f3f6ce1beb081f64504ff0a012c077680ab12","applicability":"formalized","reason":"The rule admits explicit source mathematics: Eq. (6) bounds main-grid power transfer by line capacity and the islanding indicator; Eqs. (7)-(10) define the one-sided positive power-transfer deviation using binary delta; the objective in Eq. (1) penalizes nu_m times the positive deviation. The absolute-deviation alternative is described only textually, so only its penalized magnitude is formalized. All objects are bound to the existing unary node execution.energy_trade; this rule has no graph edges. B evidence remains unreviewed, so this is a provisional formalization.","bindings":[{"object_id":"v141-c-R006-X001","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"P^{M}_{mt} is the executed main-grid power-transfer decision governed by execution.energy_trade. This rule's frozen graph supplies only the unary function node and no edges."},{"object_id":"v141-c-R006-X002","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Delta P^M_{mt} is the auxiliary deviation of the executed main-grid transfer from the DMO assignment; it belongs to the same execution.energy_trade function."},{"object_id":"v141-c-R006-X003","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Delta P^{M+}_{mt} is the positive-deviation variable selected in the execution energy-trade penalty formulation."},{"object_id":"v141-c-R006-X004","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"delta_{mt} is the binary selector used by execution.energy_trade to identify whether the power-transfer deviation is positive and penalized."},{"object_id":"v141-c-R006-T001","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"PD^M_{mt} is the DMO-assigned power input against which execution.energy_trade compares the scheduled main-grid transfer."},{"object_id":"v141-c-R006-T002","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"nu_m is the source penalty coefficient applied to the positive deviation in the execution.energy_trade objective term."},{"object_id":"v141-c-R006-T003","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"P^{M,max}_m is the line-capacity bound on the executed main-grid transfer in Eq. (6)."},{"object_id":"v141-c-R006-T004","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"U_{mt} is the islanding indicator parameter that zeros the executed main-grid transfer when it is 0."},{"object_id":"v141-c-R006-T005","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"epsilon is the positive offset appearing in the execution.energy_trade positive-deviation linearization in Eq. (10)."},{"object_id":"v141-c-R006-C002","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Eq. (6) directly constrains the executed main-grid power transfer via the line-capacity limit and islanding indicator; this is a unary constraint on execution.energy_trade."},{"object_id":"v141-c-R006-C003","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"With U_{mt}=0, the two-sided bound in Eq. (6) forces P^M_{mt}=0, so islanded execution has zero main-grid transfer."},{"object_id":"v141-c-R006-C004","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Eqs. (7)-(10) define the one-sided positive deviation for execution.energy_trade, and the objective term nu_m Delta P^{M+}_{mt} applies the penalty."},{"object_id":"v141-c-R006-C005","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"The delta=0 branch of (8)-(10) makes Delta P^{M+}_{mt}=0 when the deviation is nonpositive, leaving no positive-deviation penalty term in execution.energy_trade."},{"object_id":"v141-c-R006-C006","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"The alternative scenario penalizes the absolute power-transfer deviation, so only the penalized magnitude |Delta P^M_{mt}| is source-supported for execution.energy_trade."}],"revision_requests":["Confirm source Eq. (10) notation: B evidence v141-b-g01-e024 and v141-b-g02-E10 render Delta P^M_{mt}, while the page OCR omits the Delta symbol; verify against the page image before final source audit.","The absolute-deviation alternative in C006 is described only textually and no penalty coefficient or explicit equation is supplied; only the penalized magnitude |Delta P^M_{mt}| is formalized.","C.1 supplied only the unary node execution.energy_trade and no typed variable/parameter or edge nodes for this rule. Current bindings use that existing node only; if the ontology requires explicit variable/edge nodes for P^M, Delta P^M, Delta P^{M+}, and delta, C.1 should add them."]}},"quarantined_references":[]}});
